using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class EvalTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.GenerateReportAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var chatConfig = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(
                Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatClientForEvaluation: CreateJudgeChatClient());

        return chatConfig;
    }

    private static IChatClient CreateJudgeChatClient()
    {
        // Use the same model endpoint for evaluation judgments.
        // Configure via environment variables:
        //   AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set AZURE_OPENAI_ENDPOINT environment variable.");

        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set AZURE_OPENAI_API_KEY environment variable.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        await using var scenario = await s_reportingConfiguration!
            .CreateScenarioRunAsync(nameof(Chat_ReturnsCoherentResponse));

        var chatClient = scenario.ChatClient
            ?? throw new InvalidOperationException("Chat client not configured.");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
    }

    [TestMethod]
    public async Task Chat_FollowsInstructions()
    {
        await using var scenario = await s_reportingConfiguration!
            .CreateScenarioRunAsync(nameof(Chat_FollowsInstructions));

        var chatClient = scenario.ChatClient
            ?? throw new InvalidOperationException("Chat client not configured.");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly one sentence."),
            new(ChatRole.User, "Explain what unit testing is.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
    }

    [TestMethod]
    public async Task Chat_GroundedInContext()
    {
        await using var scenario = await s_reportingConfiguration!
            .CreateScenarioRunAsync(nameof(Chat_GroundedInContext));

        var chatClient = scenario.ChatClient
            ?? throw new InvalidOperationException("Chat client not configured.");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System,
                "You are a helpful assistant. Use only the following context to answer: " +
                "The Contoso company was founded in 2020 and has 500 employees."),
            new(ChatRole.User, "How many employees does Contoso have?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
    }
}

